// Reproduces CPython 3.11-3.15 behaviour (PSF-2.0); character data from each version's unicodedata.
//! The Python `str` semantics Trafilatura relies on, for the caller's CPython (`unicodedata`)
//! version: `isspace`/`split`/`strip` (the same in every version), `isprintable`, `lower` (with
//! the final-sigma rule), `isdecimal` and `int()` of decimal strings, `splitlines`, NFC,
//! `html.unescape`, and the character classes `re` uses (`\s`, `\w`, `re.IGNORECASE`).
//!
//! `\w`, `\d` and `isspace` come from [`crate::filters::unicode`]; the rest from `tables.rs`,
//! generated by `generate_tables.py` from CPython 3.11-3.15.

use std::borrow::Cow;

use unicode_normalization::{IsNormalized, UnicodeNormalization, is_nfc_quick};

use super::tables;
use crate::ftfy::UnicodeVersion;

/// Index of `v` in the generated per-version tables (0 = Unicode 14.0).
fn vidx(v: UnicodeVersion) -> u8 {
    match v {
        UnicodeVersion::V14_0 => 0,
        UnicodeVersion::V15_0 => 1,
        UnicodeVersion::V15_1 => 2,
        UnicodeVersion::V16_0 => 3,
        UnicodeVersion::V17_0 => 4,
    }
}

fn in_ranges(t: &[(u32, u32)], c: u32) -> bool {
    let after = t.partition_point(|&(lo, _)| lo <= c);
    after > 0 && c <= t[after - 1].1
}

/// `c.isspace()`, also `str.split()`/`strip()` and `re`'s `\s` (the same in every version).
#[inline]
pub fn is_space(c: char) -> bool {
    crate::text::is_py_whitespace(c)
}

/// `re`'s `\w` for a str pattern: `c.isalnum()` or `_`.
#[inline]
pub fn is_word(c: char, v: UnicodeVersion) -> bool {
    crate::filters::unicode::is_word(c, v)
}

/// `c.isdecimal()` (`re`'s `\d`).
#[inline]
pub fn is_decimal(c: char, v: UnicodeVersion) -> bool {
    crate::filters::unicode::is_digit(c, v)
}

/// The digit value of a `str.isdecimal()` character: decimal digits come in runs of ten
/// consecutive code points from zero (checked by the generator in every version).
pub fn decimal_value(c: char, v: UnicodeVersion) -> Option<u32> {
    if c.is_ascii_digit() {
        return Some(u32::from(c) - u32::from('0'));
    }
    if !is_decimal(c, v) {
        return None;
    }
    let mut start = u32::from(c);
    while start > 0 && char::from_u32(start - 1).is_some_and(|p| is_decimal(p, v)) {
        start -= 1;
    }
    Some((u32::from(c) - start) % 10)
}

/// `c.isprintable()`.
#[inline]
pub fn is_printable(c: char, v: UnicodeVersion) -> bool {
    let u = u32::from(c);
    if u < 0x80 {
        return (0x20..0x7f).contains(&u);
    }
    let t: &[(u32, u32)] = match vidx(v) {
        0 => &tables::PRINTABLE_14_0_0,
        1 => &tables::PRINTABLE_15_0_0,
        2 => &tables::PRINTABLE_15_1_0,
        3 => &tables::PRINTABLE_16_0_0,
        _ => &tables::PRINTABLE_17_0_0,
    };
    in_ranges(t, u)
}

/// `len(s)`: code points.
#[inline]
pub fn py_len(s: &str) -> usize {
    if s.is_ascii() {
        s.len()
    } else {
        s.chars().count()
    }
}

/// `s.isspace()`: non-empty and only whitespace.
pub fn str_isspace(s: &str) -> bool {
    !s.is_empty() && s.chars().all(is_space)
}

/// utils.text_chars_test: `bool(s and not s.isspace())`.
pub fn text_chars_test(s: Option<&str>) -> bool {
    matches!(s, Some(s) if !s.is_empty() && !s.chars().all(is_space))
}

/// `s.strip()`.
pub fn strip(s: &str) -> &str {
    s.trim_matches(is_space)
}
/// `s.lstrip()`.
pub fn lstrip(s: &str) -> &str {
    s.trim_start_matches(is_space)
}

/// `s.split()` without arguments.
pub fn split_ws(s: &str) -> impl Iterator<Item = &str> {
    s.split(is_space).filter(|x| !x.is_empty())
}

/// utils.trim: `" ".join(s.split()).strip()`.
pub fn trim(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for w in split_ws(s) {
        if !out.is_empty() {
            out.push(' ');
        }
        out.push_str(w);
    }
    out
}

/// utils.trim on an optional string (`trim(None)` is `""`).
pub fn trim_opt(s: Option<&str>) -> String {
    s.map(trim).unwrap_or_default()
}

/// `trim(s) or None`.
pub fn trim_or_none(s: Option<&str>) -> Option<String> {
    let t = trim_opt(s);
    (!t.is_empty()).then_some(t)
}

/// Whether `c` ends a line for `str.splitlines()`.
#[inline]
pub fn is_line_break(c: char) -> bool {
    matches!(
        c,
        '\n' | '\x0b'
            | '\x0c'
            | '\r'
            | '\x1c'
            | '\x1d'
            | '\x1e'
            | '\u{85}'
            | '\u{2028}'
            | '\u{2029}'
    )
}

/// `s.splitlines()` (no keepends).
pub fn splitlines(s: &str) -> Vec<&str> {
    let mut out = Vec::new();
    let b = s.as_bytes();
    let mut start = 0;
    let mut it = s.char_indices();
    while let Some((i, c)) = it.next() {
        if is_line_break(c) {
            out.push(&s[start..i]);
            let mut end = i + c.len_utf8();
            if c == '\r' && b.get(end) == Some(&b'\n') {
                it.next();
                end += 1;
            }
            start = end;
        }
    }
    if start < s.len() {
        out.push(&s[start..]);
    }
    out
}

/// The character `re.IGNORECASE` treats as the ASCII lower-case letter it matches, if any:
/// ASCII letters and U+0130, U+0131 (i), U+017F (s), U+212A (k). Other characters unchanged.
#[inline]
pub fn icase_fold(c: char) -> char {
    if c.is_ascii() {
        return c.to_ascii_lowercase();
    }
    let u = u32::from(c);
    match tables::ICASE_EXTRA.binary_search_by_key(&u, |&(k, _)| k) {
        Ok(i) => char::from(tables::ICASE_EXTRA[i].1),
        Err(_) => c,
    }
}

fn cased(c: char, v: UnicodeVersion) -> bool {
    let t: &[(u32, u32)] = match vidx(v) {
        0 => &tables::CASED_14_0_0,
        1 => &tables::CASED_15_0_0,
        2 => tables::CASED_15_1_0,
        3 => &tables::CASED_16_0_0,
        _ => &tables::CASED_17_0_0,
    };
    in_ranges(t, u32::from(c))
}

fn case_ignorable(c: char, v: UnicodeVersion) -> bool {
    let t: &[(u32, u32)] = match vidx(v) {
        0 => &tables::CASE_IGNORABLE_14_0_0,
        1 => &tables::CASE_IGNORABLE_15_0_0,
        2 => tables::CASE_IGNORABLE_15_1_0,
        3 => &tables::CASE_IGNORABLE_16_0_0,
        _ => &tables::CASE_IGNORABLE_17_0_0,
    };
    in_ranges(t, u32::from(c))
}

/// `str.lower()` of one character other than U+03A3, appended to `out`.
fn push_lower(c: char, v: UnicodeVersion, out: &mut String) {
    if c.is_ascii() {
        out.push(c.to_ascii_lowercase());
        return;
    }
    let u = u32::from(c);
    match tables::LOWER.binary_search_by_key(&u, |&(k, _, _)| k) {
        Ok(i) if tables::LOWER[i].2 <= vidx(v) => out.push_str(tables::LOWER[i].1),
        _ => out.push(c),
    }
}

/// `s.lower()`, including CPython's Final_Sigma rule for U+03A3.
pub fn lower(s: &str, v: UnicodeVersion) -> Cow<'_, str> {
    if s.is_ascii() {
        if !s.bytes().any(|b| b.is_ascii_uppercase()) {
            return Cow::Borrowed(s);
        }
        return Cow::Owned(s.to_ascii_lowercase());
    }
    let mut out = String::with_capacity(s.len());
    if !s.contains('\u{3a3}') {
        for c in s.chars() {
            push_lower(c, v, &mut out);
        }
        return if out == s {
            Cow::Borrowed(s)
        } else {
            Cow::Owned(out)
        };
    }
    let cs: Vec<char> = s.chars().collect();
    for (i, &c) in cs.iter().enumerate() {
        if c != '\u{3a3}' {
            push_lower(c, v, &mut out);
            continue;
        }
        // handle_capital_sigma: \p{cased}\p{case-ignorable}* U+03A3 !(\p{case-ignorable}* \p{cased})
        let before = cs[..i].iter().rev().find(|&&p| !case_ignorable(p, v));
        let mut fin = before.is_some_and(|&p| cased(p, v));
        if fin {
            let after = cs[i + 1..].iter().find(|&&p| !case_ignorable(p, v));
            fin = after.is_none_or(|&p| !cased(p, v));
        }
        out.push(if fin { '\u{3c2}' } else { '\u{3c3}' });
    }
    Cow::Owned(out)
}

/// `unicodedata.normalize("NFC", s)` with version `v`'s data. Characters unassigned in `v` are
/// inert there (no decomposition, class 0, never composed), so the text between them is
/// normalized with the newer data of `unicode-normalization` and they are copied through.
pub fn nfc(s: &str, v: UnicodeVersion) -> Cow<'_, str> {
    if s.is_ascii() || is_nfc_quick(s.chars()) == IsNormalized::Yes {
        return Cow::Borrowed(s);
    }
    let mut out = String::with_capacity(s.len() + 8);
    let mut run_start = 0;
    for (i, c) in s.char_indices() {
        let u = u32::from(c);
        if u >= 0x300 && !crate::ftfy::chardata::is_assigned(u, v) {
            out.extend(s[run_start..i].chars().nfc());
            out.push(c);
            run_start = i + c.len_utf8();
        }
    }
    out.extend(s[run_start..].chars().nfc());
    if out == s {
        Cow::Borrowed(s)
    } else {
        Cow::Owned(out)
    }
}

/// `s.isprintable()`.
pub fn str_isprintable(s: &str, v: UnicodeVersion) -> bool {
    s.chars().all(|c| is_printable(c, v))
}

/// utils.remove_control_characters: `s` if `s.isprintable()`, else its printable and
/// whitespace characters.
pub fn remove_control_characters(s: &str, v: UnicodeVersion) -> Cow<'_, str> {
    if str_isprintable(s, v) {
        return Cow::Borrowed(s);
    }
    Cow::Owned(
        s.chars()
            .filter(|&c| is_printable(c, v) || is_space(c))
            .collect(),
    )
}

/// lxml's `_is_valid_xml_utf8`: what `.text`, `.tail` and attribute values accept (no C0
/// control but TAB, LF, CR; no U+FFFE, U+FFFF; a Rust string has no surrogates).
pub fn xml_valid(s: &str) -> bool {
    let b = s.as_bytes();
    for (i, &x) in b.iter().enumerate() {
        if x < 0x20 {
            if !matches!(x, b'\t' | b'\n' | b'\r') {
                return false;
            }
        } else if x == 0xEF
            && b.get(i + 1) == Some(&0xBF)
            && matches!(b.get(i + 2), Some(0xBE | 0xBF))
        {
            return false;
        }
    }
    true
}

/// A Python exception that escapes the code being ported (it is not caught there).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PyError {
    /// `ValueError` from `int()` of more than 4300 decimal digits (`html.unescape` of a long
    /// `&#...` reference): "Exceeds the limit (4300 digits) for integer string conversion: value
    /// has {digits} digits; use sys.set_int_max_str_digits() to increase the limit".
    IntMaxStrDigits { digits: usize },
}

/// `sys.get_int_max_str_digits()` default: `int()` of a longer decimal string raises.
const INT_MAX_STR_DIGITS: usize = 4300;

/// `html.unescape(s)`.
pub fn html_unescape(s: &str) -> Result<Cow<'_, str>, PyError> {
    if !s.contains('&') {
        return Ok(Cow::Borrowed(s));
    }
    let mut out = String::with_capacity(s.len());
    let mut rest = s;
    while let Some(pos) = rest.find('&') {
        out.push_str(&rest[..pos]);
        let after = &rest[pos + 1..];
        if let Some((consumed, repl)) = charref(after)? {
            out.push_str(&repl);
            rest = &after[consumed..];
        } else {
            out.push('&');
            rest = after;
        }
    }
    out.push_str(rest);
    Ok(Cow::Owned(out))
}

/// One `html._charref` match at the start of `s` (the text after '&'): bytes consumed and the
/// replacement, or None when the pattern does not match there.
fn charref(s: &str) -> Result<Option<(usize, Cow<'static, str>)>, PyError> {
    let b = s.as_bytes();
    if b.first() == Some(&b'#') {
        // '#[0-9]+;?' | '#[xX][0-9a-fA-F]+;?'
        let (hex, digits_start) = if matches!(b.get(1), Some(b'x' | b'X')) {
            (true, 2)
        } else {
            (false, 1)
        };
        let mut j = digits_start;
        while j < b.len()
            && (if hex {
                b[j].is_ascii_hexdigit()
            } else {
                b[j].is_ascii_digit()
            })
        {
            j += 1;
        }
        if j == digits_start {
            // '#x' without digits: no alternative matches ('[^...#;]' cannot start with '#')
            return Ok(None);
        }
        if !hex && j - digits_start > INT_MAX_STR_DIGITS {
            return Err(PyError::IntMaxStrDigits {
                digits: j - digits_start,
            });
        }
        let end = if b.get(j) == Some(&b';') { j + 1 } else { j };
        let num = parse_saturating(&b[digits_start..j], if hex { 16 } else { 10 });
        let repl: Cow<'static, str> =
            if let Ok(i) = tables::INVALID_CHARREFS.binary_search_by_key(&num, |&(k, _)| k) {
                Cow::Borrowed(tables::INVALID_CHARREFS[i].1)
            } else if (0xD800..=0xDFFF).contains(&num) || num > 0x10_FFFF {
                Cow::Borrowed("\u{FFFD}")
            } else if tables::INVALID_CODEPOINTS.binary_search(&num).is_ok() {
                Cow::Borrowed("")
            } else {
                char::from_u32(num).map_or(Cow::Borrowed("\u{FFFD}"), |c| Cow::Owned(c.to_string()))
            };
        return Ok(Some((end, repl)));
    }
    // '[^\t\n\f <&#;]{1,32};?'
    let mut n = 0usize;
    let mut end = 0usize;
    for (i, c) in s.char_indices() {
        if n == 32 || matches!(c, '\t' | '\n' | '\x0c' | ' ' | '<' | '&' | '#' | ';') {
            break;
        }
        n += 1;
        end = i + c.len_utf8();
    }
    if n == 0 {
        return Ok(None);
    }
    let name_end = if b.get(end) == Some(&b';') {
        end + 1
    } else {
        end
    };
    let name = &s[..name_end];
    if let Some(v) = html5(name) {
        return Ok(Some((name_end, Cow::Borrowed(v))));
    }
    // the longest prefix that is an entity, of x code points for x = len - 1 down to 2
    let idx: Vec<usize> = name
        .char_indices()
        .map(|(i, _)| i)
        .chain([name.len()])
        .collect();
    let nchars = idx.len() - 1;
    for x in (2..nchars).rev() {
        if let Some(v) = html5(&name[..idx[x]]) {
            return Ok(Some((
                name_end,
                Cow::Owned(format!("{v}{}", &name[idx[x]..])),
            )));
        }
    }
    Ok(Some((name_end, Cow::Owned(format!("&{name}")))))
}

fn parse_saturating(digits: &[u8], radix: u32) -> u32 {
    let mut v: u64 = 0;
    for &d in digits {
        v = v * u64::from(radix) + u64::from(char::from(d).to_digit(radix).unwrap_or(0));
        if v > 0x7FFF_FFFF {
            return u32::MAX;
        }
    }
    u32::try_from(v).unwrap_or(u32::MAX)
}

fn html5(name: &str) -> Option<&'static str> {
    tables::HTML5
        .binary_search_by(|&(k, _)| k.cmp(name))
        .ok()
        .map(|i| tables::HTML5[i].1)
}

#[cfg(test)]
mod tests {
    use super::*;
    const V: UnicodeVersion = UnicodeVersion::V15_1;

    #[test]
    fn unescape_cases() {
        let u = |s: &str| html_unescape(s).unwrap().into_owned();
        assert_eq!(u("a &amp; b"), "a & b");
        assert_eq!(u("&amp"), "&");
        assert_eq!(u("&ampx"), "&x");
        assert_eq!(u("&notit;"), "¬it;");
        assert_eq!(u("&#65;&#x42;&#0;"), "AB\u{FFFD}");
        assert_eq!(u("&#128;"), "\u{20AC}");
        assert_eq!(u("&#1;"), "");
        assert_eq!(u("&zz;"), "&zz;");
        assert_eq!(u("& x"), "& x");
        assert_eq!(u("&#x;"), "&#x;");
        assert_eq!(u("&#99999999999999;"), "\u{FFFD}");
        let long = format!("&#{}", "1".repeat(4301));
        assert_eq!(
            html_unescape(&long),
            Err(PyError::IntMaxStrDigits { digits: 4301 })
        );
        let ok = format!("&#x{}", "1".repeat(5000));
        assert_eq!(u(&ok), "\u{FFFD}");
    }

    #[test]
    fn splitlines_cases() {
        assert_eq!(splitlines("a\r\nb\rc\n"), vec!["a", "b", "c"]);
        assert_eq!(splitlines("\n"), vec![""]);
        assert_eq!(splitlines(""), Vec::<&str>::new());
        assert_eq!(splitlines("a\n\nb"), vec!["a", "", "b"]);
    }

    #[test]
    fn trims() {
        assert_eq!(trim("  a \n b\u{a0}c  "), "a b c");
        assert_eq!(trim("\u{200b}"), "\u{200b}");
        assert!(text_chars_test(Some("\u{200b}")));
        assert!(!text_chars_test(Some(" \x1c")));
    }

    #[test]
    fn lowering() {
        assert_eq!(lower("ABC", V), "abc");
        assert_eq!(lower("İ", V), "i\u{307}");
        assert_eq!(lower("\u{212a}", V), "k");
        // final sigma
        assert_eq!(lower("ΤΗΣ", V), "της");
        assert_eq!(lower("ΣΑ", V), "σα");
        assert_eq!(lower("Σ", V), "σ");
        assert_eq!(lower("ΑΣ.", V), "ας.");
        assert_eq!(lower("ΑΣΑ", V), "ασα");
    }

    #[test]
    fn printable_and_controls() {
        assert!(is_printable(' ', V));
        assert!(!is_printable('\u{a0}', V));
        assert!(!is_printable('\u{ad}', V));
        assert_eq!(remove_control_characters("a\u{1}b\tc", V), "ab\tc");
        assert!(xml_valid("a\tb\r\n"));
        assert!(!xml_valid("a\u{c}b"));
        assert!(!xml_valid("a\u{fffe}"));
    }

    #[test]
    fn decimals() {
        assert_eq!(decimal_value('7', V), Some(7));
        assert_eq!(decimal_value('\u{0663}', V), Some(3));
        assert_eq!(decimal_value('\u{1d7d9}', V), Some(1));
        assert_eq!(decimal_value('²', V), None);
    }

    #[test]
    fn icase() {
        assert_eq!(icase_fold('İ'), 'i');
        assert_eq!(icase_fold('ſ'), 's');
        assert_eq!(icase_fold('Q'), 'q');
        assert_eq!(icase_fold('é'), 'é');
    }
}

#[cfg(test)]
mod unicode_vectors {
    //! `str.lower()`, `remove_control_characters` and NFC against CPython 3.11-3.15
    //! (`tests/trafilatura_data/unicode.json`, written by `unicode_cases.py`).
    use super::*;
    use serde_json::Value;

    #[test]
    fn match_cpython() {
        let fixture: Value =
            serde_json::from_str(include_str!("../../tests/trafilatura_data/unicode.json"))
                .unwrap();
        let inputs = &fixture["inputs"];
        let mut checked = 0;
        for (ver, out) in fixture["outputs"].as_object().unwrap() {
            let v = UnicodeVersion::from_unidata_version(ver).unwrap();
            for (key, f) in [
                (
                    "lower",
                    (|s: &str, v| lower(s, v).into_owned()) as fn(&str, UnicodeVersion) -> String,
                ),
                ("printable", |s, v| {
                    remove_control_characters(s, v).into_owned()
                }),
                ("nfc", |s, v| nfc(s, v).into_owned()),
            ] {
                let ins = inputs[key].as_array().unwrap();
                let want = out[key].as_array().unwrap();
                for (i, w) in ins.iter().zip(want) {
                    let (i, w) = (i.as_str().unwrap(), w.as_str().unwrap());
                    assert_eq!(f(i, v), w, "{key} of {i:?} with Unicode {ver}");
                    checked += 1;
                }
            }
        }
        assert!(checked > 2000);
    }
}
